import java.util.*;

class Solution {
    public boolean sameLetters(String a, String b) {
        if (a.length() != b.length()) return false;
        int[] cnt = new int[26];
        for (int i = 0; i < a.length(); i++) cnt[a.charAt(i) - 'a']++; // add letters of a
        for (int i = 0; i < b.length(); i++) cnt[b.charAt(i) - 'a']--; // remove letters of b
        for (int i = 0; i < 26; i++) {
            if (cnt[i] != 0) return false; // some letter count differs
        }
        return true;
    }
}

