class Solution:
    def sameLetters(self, a: str, b: str) -> bool:
        if len(a) != len(b): return False
        cnt = [0] * 26
        for c in a: cnt[ord(c) - 97] += 1
        for c in b: cnt[ord(c) - 97] -= 1
        return all(x == 0 for x in cnt)

